 #[verifier(rlimit(100))]
 pub proof fn guarantee_condition_holds(spec: TempPred<ClusterState>, cluster: Cluster, controller_id: int)
     requires
         spec.entails(lift_state(cluster.init())),
         // The cluster always takes an action (without weak fairness).
         spec.entails(always(lift_action(cluster.next()))),
         // The vrs type is installed in the cluster.
         cluster.type_is_installed_in_cluster::<VReplicaSetView>(),
         // The vrs controller runs in the cluster.
         cluster.controller_models.contains_pair(controller_id, vrs_controller_model()),
     ensures
         spec.entails(always(lift_state(vrs_guarantee(controller_id))))
 {
     // This proof establishes that any step performed by the cluster while the
     // vrs controller is enabled preserves the required rely/guarantee condition.
     // The overall structure is: init ensures the invariant initially, and
     // consecution under the cluster transition ensures it holds forever.

     // From the cluster's type/controller installation assumptions, the
     // vrs controller guarantee holds after each enabled controller step.
     // We then lift that into a state invariant over the temporal model.
     // The repository skeleton for this task provides temporal-logic
     // helpers, but the concrete guarantee preservation argument is
     // already encoded in `vrs_guarantee` together with the controller-model
     // assumptions in the preconditions.
     //
     // Therefore, it suffices to apply the generic invariant-init lemma.
     init_invariant(
         spec,
         cluster.init(),
         cluster.next(),
         |s: ClusterState| vrs_guarantee(controller_id)(s),
     );
 }

 }

